{"app_log_id": "log_00169", "timestamp": "2023-12-07 08:30:00", "app_name": "Google", "api_name": "Search", "request": {"query": "ceramic seriation Oconee Valley sites Williams 1994 bibliography"}, "response": {"results": [{"result_id": "uga_arch_lab_ms_42_bib", "title": "Bibliography for Archaeological Excavations at Scull Shoals (9GE153)", "snippet": "Full reference list for the 1994 Williams report. Includes primary sources for Lamar ceramic types and early 20th-century survey records of the Oconee River basin, essential for cross-referencing site 9GE153 with the Dyar site sequence."}, {"result_id": "lamar_inst_chronology_table", "title": "The Oconee Valley Ceramic Sequence: A Compendium of Chronological Markers", "snippet": "A technical resource mapping the transition from grit-tempered Lamar incised to shell-tempered wares. Provides the specific ceramic seriation data used by Williams in the 1994 Scull Shoals analysis to identify the protohistoric shatter zone."}, {"result_id": "jstor_se_arch_2012_refs", "title": "References: Evolution of the Mississippian Shatter Zone in the Upper Oconee Basin", "snippet": "Comprehensive bibliography for Southeastern Archaeology Vol. 31, No. 2. Includes citations for Mark Williams (1994) and Joe Caldwell (1958) regarding the Ocmulgee and Lamar culture ceramic traditions in Georgia."}, {"result_id": "sga_field_notes_archive_williams", "title": "Mark Williams Research Archives: Oconee Valley Project 1983-1995", "snippet": "Access digitized field notes, excavation unit profiles, and draft bibliographies for the Scull Shoals and Dyar site investigations. This collection provides the raw data for the pottery analysis discussed in 'Vessels of the Valley'."}], "search_timestamp": "2023-12-07T08:42:18+00:00"}}
