{"app_log_id": "log_00068", "timestamp": "2023-10-25 13:45:00", "app_name": "Google", "api_name": "Search", "request": {"query": "hands-on lithic analysis field seminars Georgia 2024"}, "response": {"results": [{"result_id": "sga_workshop_2024_01", "title": "2024 Advanced Lithic Analysis Workshop - Society for Georgia Archaeology", "snippet": "A three-day intensive seminar focusing on debitage analysis and experimental knapping. Held at the Ocmulgee Mounds laboratory, this hands-on workshop provides practical experience in identifying Southeastern chert sources and reduction strategies."}, {"result_id": "seac_field_methods_2024", "title": "Southeastern Archaeology Conference: Spring 2024 Technical Seminars", "snippet": "Registration is now open for our 'Tactile Technologies' series in Savannah. These seminars move beyond digital modeling to focus on macroscopic identification and geochemical sourcing techniques for Georgia Piedmont assemblages."}, {"result_id": "ga_dnr_hpd_lithics_24", "title": "Georgia DNR Historic Preservation Division: Stone Tool Identification Series", "snippet": "Specifically designed for professionals and advanced graduate students, this 2024 series offers laboratory-based instruction on diagnostic projectile point types of the South Atlantic Slope with direct access to type collections."}, {"result_id": "fernbank_arch_lithic_intensive", "title": "Lithic Technology and Microwear Analysis: 2024 Summer Intensive", "snippet": "Join leading experts for a week-long field seminar in Atlanta. This program emphasizes hands-on microscopic analysis and experimental archaeology, bypassing lecture-heavy formats for direct artifact engagement."}], "search_timestamp": "2023-10-25T13:48:12+00:00"}}
