{"app_log_id": "log_00133", "timestamp": "2023-11-21 08:30:00", "app_name": "Google", "api_name": "Search", "request": {"query": "ceramic evidence for the Mississippian shatter zone in the Oconee Valley shell-tempered distribution"}, "response": {"results": [{"result_id": "jstor_230491_shatter_zone", "title": "Mapping the Mississippian Shatter Zone: Ceramic Evidence from the Upper Oconee", "snippet": "This seminal paper examines the 16th-century transition in the Oconee Valley, specifically identifying the introduction of shell-tempered wares as a diagnostic marker for population displacement and social upheaval during the shatter zone period."}, {"result_id": "uga_arch_lab_ms_51_dyar", "title": "The Dyar Site (9GE5) and the Protohistoric Oconee Valley Ceramic Sequence", "snippet": "University of Georgia Laboratory of Archaeology Manuscript No. 51. Provides a detailed comparative analysis of ceramic assemblages from the Dyar and Scull Shoals sites, focusing on the late Lamar phases and the intrusion of shell-tempered types."}, {"result_id": "se_arch_journal_2019_williams", "title": "Continuity and Change in the Oconee River Valley: 1450–1650", "snippet": "In this updated review, Mark Williams discusses the spatial distribution of grit-tempered vs. shell-tempered pottery across 9GE153, arguing for a more complex model of local adaptation amidst regional Mississippian collapse."}, {"result_id": "lamar_inst_shatter_zone_symposium", "title": "The Mississippian Shatter Zone: 2023 Symposium Proceedings", "snippet": "A collection of recent papers discussing the archaeological visibility of the 'shatter zone.' Includes a chapter on the Oconee basin ceramic chronologies and the geochemical sourcing of shell-tempered sherds found in the 1992 Scull Shoals excavations."}], "search_timestamp": "2023-11-21T08:44:12+00:00"}}

