{"app_log_id": "log_00062", "timestamp": "2023-10-22 20:00:00", "app_name": "Google", "api_name": "Search", "request": {"query": "new National Geographic archaeology series Disney Plus"}, "response": {"results": [{"result_id": "natgeo_lin_lost_cities_2023", "title": "Lost Cities with Albert Lin - National Geographic Documentary Series | Disney+", "snippet": "Using cutting-edge LiDAR technology and ground-penetrating radar, Dr. Albert Lin travels from the Mayan jungles to the Israeli desert to uncover hidden structures and ancient civilizations. Stream the latest season now."}, {"result_id": "natgeo_tut_treasures_new", "title": "Tut's Treasures: Hidden Secrets - Disney+ National Geographic", "snippet": "Explore the newest archaeological findings regarding the boy king. This series features exclusive access to the relocation of King Tutankhamun's artifacts to the Grand Egyptian Museum and the latest excavations in the Valley of the Kings."}, {"result_id": "natgeo_ancient_china_2023", "title": "Ancient China from Above: New Discoveries - Watch on Disney+", "snippet": "Archaeologists use satellite imagery and drone technology to reveal the engineering marvels of early Chinese dynasties. A fascinating look at the scale of ancient urban planning and infrastructure."}, {"result_id": "disney_natgeo_collection_arch", "title": "National Geographic: The Archaeology Collection - Official Disney+", "snippet": "Browse curated historical and archaeological series including 'Drain the Oceans', 'Lost Treasures of the Maya', and 'Kingdom of the Mummies'. High-quality educational content for history and archaeology enthusiasts."}], "search_timestamp": "2023-10-22T20:04:18+00:00"}}

